var n=`1017-khanom-krok`;var a=`world-1017`;var t=`TH`;var s=`southeast-asia`;var o=8;var r=39;var l={en:`Khanom Krok`,ua:`Каном крок`};var h={en:`Khanom Krok is a dish from Thailand prepared with rice flour, coconut milk, pandan leaves, green onion. This is a home-scale version with measured ingredients in the individual steps where they are used. Pandan leaves are infused rather than using pandan extract; a round-cavity skillet makes the characteristic shape.`,ua:`Каном крок, страва кухні країни Таїланд, яку готують із таких продуктів: рисове борошно, кокосове молоко, листя пандану, зелена цибуля. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Листя пандану настоюють замість екстракту; характерну форму дає сковорода з круглими заглибинами.`};var d=[{en:`Whisk the listed batter ingredients until smooth. Let the mixture rest briefly so the flour hydrates.`,ua:`Збийте складники рідкого тіста до однорідності. Дайте суміші коротко відпочити, щоб борошно увібрало вологу.`,t:[`mixing`,`whisking`],m:10,i:[[`rice-flour`,220,`g`],[`coconut-milk`,480,`ml`],[`white-granulated-sugar`,95,`g`],[`table-salt`,4,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:4,i:[[`pandan-leaves`,2,`leaf`]]},{en:`Cook the coconut-rice batter in a khanom krok or takoyaki pan with small round wells, covering briefly so each cake sets with crisp edges.`,ua:`Готуйте кокосово-рисове тісто у формі для каном крок або такоякі з маленькими круглими комірками, ненадовго накриваючи для схоплення й хрустких країв.`,t:[`pan-frying`],m:22,i:[[`coconut-oil`,35,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`green-onion`,25,`g`],[`coconut-cream`,120,`ml`]]}];var u={slug:n,id:a,country:`TH`,region:s,servings:8,minutes:39,title:l,text:h,steps:d};export{t as country,u as default,a as id,r as minutes,s as region,o as servings,n as slug,d as steps,h as text,l as title};